from dspy.predict import BestOfN
import dspy
from dspy.utils.dummies import DummyLM

lm = DummyLM([{'answer': 'Brussels'}, {'answer': 'City of Brussels'}, {'answer': 'Brussels'}])
dspy.settings.configure(lm=lm)

class DummyModule(dspy.Module):
    def __init__(self, forward_fn):
        super().__init__()
        self.forward_fn = forward_fn
    def forward(self, **kwargs):
        return self.forward_fn(**kwargs)

# Test default fail_count: all 3 attempts fail, should raise
def always_fail(**kwargs):
    raise ValueError('Failed')

module = DummyModule(always_fail)

best = BestOfN(module=module, N=3, reward_fn=lambda _, __: 1.0, threshold=0.0)
try:
    best()
    print('ERROR: Should have raised')
except ValueError as e:
    print('OK: Default fail_count raises when all attempts fail:', e)
"

